#define BUILD_FINAL 1

typedef unsigned int uint32;

class vector3d
{
  float data[4];
};

class quaternion
{
  float data[4];
};

class KSEntityPO
{
  vector3d KSPos;
  vector3d KSBPos;
  quaternion KSRot;
  quaternion KSBRot;
  vector3d BoardCurrent;
  vector3d BoardMomentum;

public:
  void Save(int player);
};

class KSEntityState
{
  uint32 KSState : 7;
  uint32 KSSuperState : 4;
  uint32 KSAnim : 10;
  uint32 KSBAnim : 8;
  uint32 KSBlend : 7;
  uint32 KSBBlend : 7;
  uint32 KSCurTrick : 7;
  uint32 KSAnimCall : 1;
  uint32 KSBAnimCall : 1;
  uint32 KSLoop : 1;
  uint32 KSBLoop : 1;
  uint32 KSWipedOut : 1;
  uint32 KSInAir : 1;
  uint32 KSInTube : 1;
  uint32 KSDry : 1;
  uint32 KSIKValid : 1;
  uint32 KSWipeoutSplash : 1;
  uint32 EndWave : 1;
  uint32 padding : 3;

public:
  void Reset();
  void Save(int player);
};

class KSReplayFrame
{
  float wave_shiftx;
  float levelTime;
  float totalTime;

public:
  void Save();
};

class KSWaterState
{
public:
  void Save();
};

struct nglFileBuf
{
  void *Buf;
  unsigned int Size;
};

class DemoModeManager
{
  float totalTime;
  float timeoutDelay;
  float demoDuration;
  float demoTime;
  bool inDemo;
  bool played;
  bool demoStarted;
  char fname[24];
  bool wasInTitle;

public:
  unsigned int replayFrames;
  unsigned int replayMainPOFrames;
  unsigned int replayAIPOFrames;
  nglFileBuf replayFile;

  bool inDemoMode();
};

extern DemoModeManager dmm;

const unsigned int MAINENTITY_UPDATEFRAMES = 4;
const unsigned int AIENTITY_UPDATEFRAMES = 8;

class KSReplay
{
public:
  int bch, sfr, brd;

private:
  uint32 seed;
  int status;
  float playtime;
  float lastPlaytime;
  bool slomo;
  bool fastforward;
  bool prepareSlomo;
  bool prepareNormal;
  int slomospeed;
  int ffspeed;
  unsigned int playframe;
  int lastPlayframe;
  int interpFrame;
  unsigned int mainPOFrame;
  unsigned int aiPOFrame;
  int frameTicks;
  int interpTicks;
  bool aiSurfer;
  unsigned int numFrames;
  unsigned int numMainPOFrames;
  unsigned int numAIPOFrames;
  KSReplayFrame *frame;
  KSEntityState *mainEntityState;
  KSEntityState *aiEntityState;
  KSEntityPO *mainEntityPO;
  KSEntityPO *aiEntityPO;
  unsigned int maxframes;
  bool noDraw;
  KSWaterState initWaterState;

public:
  virtual ~KSReplay();

protected:
  void SaveFrame();
};

void KSReplay::SaveFrame()
{
	unsigned int maxmainpoframes = dmm.inDemoMode() ? dmm.replayMainPOFrames : (maxframes/MAINENTITY_UPDATEFRAMES);
	unsigned int maxaipoframes   = dmm.inDemoMode() ? dmm.replayAIPOFrames   : (maxframes/AIENTITY_UPDATEFRAMES);

  if (numFrames>=maxframes || numFrames/MAINENTITY_UPDATEFRAMES>=maxmainpoframes || (aiSurfer && numFrames/AIENTITY_UPDATEFRAMES>=maxaipoframes))
    return;

  if(numFrames == 0)
  {
    mainEntityState[0].Reset();
    if(aiSurfer)
      aiEntityState[0].Reset();

    initWaterState.Save();
  }

  // BIG HACK, FIXME: find a better way
  // Don't save the frame if the current anim is the PLACEHOLDER, which seems to happen
  //  for a single frame at the beginning of a run, or just after a wipeout.
  //if(SURFER_ANIM_PLACEHOLDER == g_world_ptr->get_ks_controller(0)->GetCurrentAnim())
  //  return;

  frame[numFrames].Save();
  mainEntityState[numFrames].Save(0);
  if(numFrames%MAINENTITY_UPDATEFRAMES == 0)
  {
		#ifndef BUILD_FINAL
	  int maxmainpoframes = dmm.inDemoMode() ? dmm.replayMainPOFrames : (maxframes/MAINENTITY_UPDATEFRAMES);
		assert((int) (numFrames/MAINENTITY_UPDATEFRAMES) < maxmainpoframes);
		#endif
    mainEntityPO[numFrames/MAINENTITY_UPDATEFRAMES].Save(0);
    numMainPOFrames = numFrames/MAINENTITY_UPDATEFRAMES + 1;
  }

  if(aiSurfer)
  {
    aiEntityState[numFrames].Save(1);
    if(numFrames%AIENTITY_UPDATEFRAMES == 0)
    {
      aiEntityPO[numFrames/AIENTITY_UPDATEFRAMES].Save(1);
      numAIPOFrames = numFrames/AIENTITY_UPDATEFRAMES + 1;
    }
  }

  numFrames++;

  if (numFrames < maxframes)
  {
	  mainEntityState[numFrames].Reset();

    if (aiSurfer)
	    aiEntityState[numFrames].Reset();
  }
}
